use vstd::prelude::*;

verus! {

/// A small spec predicate for evenness over mathematical integers.
spec fn is_even(i: int) -> bool {
    i % 2 == 0
}

/// Executable function:
/// - inputs are positive i8
/// - returns the largest even in [x,y], or -1 if invalid / none.
fn choose_num(x: i8, y: i8) -> (res: i8)
    requires
        x > 0,
        y > 0,
    ensures
        // Case 1: invalid interval
        x > y ==> res == -1,

        // Case 2: valid interval but no even numbers
        x <= y ==>
            (
                (forall|k: int| x as int <= k <= y as int ==> !is_even(k)) ==> res == -1
            ),

        // Case 3: valid interval and there exists an even number -> res is the max even
        x <= y ==>
            (
                (exists|k: int| x as int <= k <= y as int && is_even(k)) ==>
                (
                    x as int <= res as int <= y as int
                    && is_even(res as int)
                    && forall|k: int|
                        x as int <= k <= y as int && is_even(k) ==> k <= res as int
                )
            ),
{
    // If interval is invalid, return -1.
    if x > y {
        return -1;
    }

    // Otherwise, pick the largest even <= y, and check it is >= x.
    // Since x,y are positive i8, y-1 won't underflow below i8::MIN here.
    let candidate: i8 = if y % 2 == 0 { y } else { y - 1 };

    if candidate < x {
        -1
    } else {
        candidate
    }
}

} // verus!

